def contar_positivos(v, tam):
    cuenta = 0
    for i in range(tam):
        if v[i] > 0:
            cuenta = cuenta + 1
    return cuenta


def main():
    numeros = [3, 0, -1, 5]
    print(contar_positivos(numeros, 4))


